package palindrome

import (
	"errors"
)

// Product holds a palindromic product together with every pair of factors
// (within the requested range) that produces it.
type Product struct {
	Product      int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic numbers that are the
// product of two numbers within the inclusive range [fmin, fmax], along with
// the factor pairs for each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var min, max Product
	found := false

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			p := i * j
			if !isPalindrome(p) {
				continue
			}
			if !found {
				min = Product{p, [][2]int{{i, j}}}
				max = min
				found = true
				continue
			}
			if p < min.Product {
				min = Product{p, [][2]int{{i, j}}}
			} else if p == min.Product {
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
			if p > max.Product {
				max = Product{p, [][2]int{{i, j}}}
			} else if p == max.Product {
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
		}
	}

	if !found {
		return Product{}, Product{}, errors.New("no palindromes")
	}

	return min, max, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
func isPalindrome(n int) bool {
	orig := n
	reversed := 0
	for n > 0 {
		reversed = reversed*10 + n%10
		n /= 10
	}
	return orig == reversed
}

